<?php require __DIR__.'/../bootstrap.php';$tok=basename((string)getv('token',''));$s=db()->prepare('SELECT * FROM shared_items WHERE token=?');$s->execute([$tok]);$x=$s->fetch();if(!$x){http_response_code(404);exit('Share not found.');}
page_start($x['type']==='message'?'Shared AI response':'Shared conversation',false);echo '<main class="legal share-page"><span class="eyebrow">PocketCat Share</span>';
if($x['type']==='message'){$s=db()->prepare('SELECT m.id,m.role,m.content,m.created_at,pm.content user_prompt FROM conversation_messages m LEFT JOIN conversation_messages pm ON pm.id=(SELECT MAX(id) FROM conversation_messages WHERE conversation_id=m.conversation_id AND role=\'user\' AND id<m.id) WHERE m.id=? AND m.role=\'assistant\'');$s->execute([$x['message_id']]);$m=$s->fetch();if(!$m){http_response_code(404);exit('Shared response not found.');}echo '<h1>Shared Q&amp;A</h1><div class="share-pair"><div class="share-q"><strong>User</strong><p>'.nl2br(e($m['user_prompt']??'')) .'</p></div><div class="share-a"><strong>AI</strong><p>'.nl2br(e($m['content'])) .'</p></div></div>';}else{$s=db()->prepare('SELECT role,content,created_at FROM conversation_messages WHERE conversation_id=? ORDER BY id');$s->execute([$x['conversation_id']]);echo '<h1>Shared conversation</h1><div class="share-thread">';foreach($s->fetchAll() as $m){echo '<article class="share-msg '.e($m['role']).'"><strong>'.e(ucfirst($m['role'])).'</strong><div>'.nl2br(e($m['content'])).'</div></article>';}echo '</div>';}echo '</main>';page_end();